package com.slotmind.exception;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(ApiExceptions.NotFound.class) ResponseEntity<?> notFound(ApiExceptions.NotFound e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));} @ExceptionHandler(ApiExceptions.Conflict.class) ResponseEntity<?> conflict(ApiExceptions.Conflict e){return ResponseEntity.status(409).body(Map.of("error",e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("error","Invalid request","details",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> illegal(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} }